@* Displays the step progress indicator with checkmarks for completed steps *@

<div class="d-flex justify-content-between align-items-center mb-4 step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var step = i;
        var isActive = step == CurrentStep;
        var isCompleted = CompletedSteps.Contains(step);
        var isFuture = !isActive && !isCompleted;

        <div class="d-flex align-items-center">
            <button class="btn btn-sm rounded-circle @(isActive ? "btn-primary" : isCompleted ? "btn-success" : "btn-outline-secondary")"
                    style="width:36px;height:36px;"
                    disabled="@isFuture"
                    @onclick="() => OnStepClicked.InvokeAsync(step)">
                @if (isCompleted)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(step + 1)</span>
                }
            </button>
            <span class="ms-2 @(isActive ? "fw-bold" : isFuture ? "text-muted" : "")">
                @StepNames[step]
            </span>
        </div>

        @if (i < StepNames.Length - 1)
        {
            <hr class="flex-grow-1 mx-2" />
        }
    }
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

@* A single work experience entry form *@

<div class="card mb-3">
    <div class="card-body">
        @if (ShowRemove)
        {
            <div class="d-flex justify-content-end">
                <button type="button" class="btn btn-sm btn-outline-danger" @onclick="OnRemove">Remove</button>
            </div>
        }

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name *</label>
                <input class="form-control" value="@Entry.Company"
                       @onchange="e => Update(Entry with { Company = (string?)e.Value ?? string.Empty })" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title *</label>
                <input class="form-control" value="@Entry.Title"
                       @onchange="e => Update(Entry with { Title = (string?)e.Value ?? string.Empty })" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date *</label>
                <input type="date" class="form-control" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                       @onchange="e => Update(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? string.Empty) })" />
            </div>
            <div class="col-md-4">
                <div class="form-check mt-4">
                    <input type="checkbox" class="form-check-input" id="@($"current-{Index}")"
                           checked="@IsCurrent"
                           @onchange="e => ToggleCurrent((bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="@($"current-{Index}")">Currently working here</label>
                </div>
            </div>
            <div class="col-md-4">
                @if (!IsCurrent)
                {
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control"
                           value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty)"
                           @onchange="e => Update(Entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
                }
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" value="@Entry.Description"
                          @onchange="e => Update(Entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null;

    private void Update(WorkEntry updated) => OnChanged.InvokeAsync(updated);

    private void ToggleCurrent(bool isCurrent)
    {
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        OnChanged.InvokeAsync(updated);
    }
}

@* A single reference entry form *@

<div class="card mb-3">
    <div class="card-body">
        @if (ShowRemove)
        {
            <div class="d-flex justify-content-end">
                <button type="button" class="btn btn-sm btn-outline-danger" @onclick="OnRemove">Remove</button>
            </div>
