@using sv_cf38e0567e67413598f0a4e1f4948835.Models

<h4>Personal Information</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

<div class="row g-3 mb-4">
    <div class="col-md-6">
        <label class="form-label">Full Name *</label>
        <input class="form-control" value="@Model.FullName"
               @onchange="e => Model = Model with { FullName = (string?)e.Value ?? string.Empty }" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Email *</label>
        <input type="email" class="form-control" value="@Model.Email"
               @onchange="e => Model = Model with { Email = (string?)e.Value ?? string.Empty }" />
        @if (IsValidatingEmail)
        {
            <small class="text-muted">Validating email...</small>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Phone *</label>
        <input type="tel" class="form-control" value="@Model.Phone"
               @onchange="e => Model = Model with { Phone = (string?)e.Value ?? string.Empty }" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Address *</label>
        <input class="form-control" value="@Model.Address"
               @onchange="e => Model = Model with { Address = (string?)e.Value ?? string.Empty }" />
    </div>
</div>

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidatingEmail">Next &raquo;</button>
</div>

@code {
    [Parameter] public PersonalInfo Model { get; set; } = new("", "", "", "");
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? ErrorMessage;
    private bool IsValidatingEmail;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        if (ValidateEmail is not null)
        {
            IsValidatingEmail = true;
            StateHasChanged();
            var isValid = await ValidateEmail(Model.Email);
            IsValidatingEmail = false;

            if (!isValid)
            {
                ErrorMessage = "Please enter a valid email address.";
                return;
            }
        }

        await OnNext.InvokeAsync(Model);
    }
}

