@page "/apply"
@rendermode InteractiveServer
@using sv_cf38e0567e67413598f0a4e1f4948835.Models
@inject IApplicationService AppService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width:800px;">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="@currentStep"
                   CompletedSteps="@completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="@personalInfo"
                              ValidateEmail="AppService.ValidateEmailAsync"
                              OnNext="OnPersonalNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnNext="OnWorkNext"
                             OnBack="OnWorkBack" />
            break;
        case 2:
            <ReferencesStep References="@references"
                            OnNext="OnReferencesNext"
                            OnBack="OnReferencesBack" />
            break;
        case 3:
            <CoverLetterStep Text="@coverLetter"
                             OnNext="OnCoverLetterNext"
                             OnBack="OnCoverLetterBack" />
            break;
        case 4:
            <ReviewStep Personal="@personalInfo"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnEdit="GoToStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep;
    private HashSet<int> completedSteps = new();

    private PersonalInfo personalInfo = new("", "", "", "");
    private List<WorkEntry> workEntries = new() { new("", "", DateTime.Today, null, "") };
    private List<Reference> references = new() { new("", "", "", ""), new("", "", "", "") };
    private string coverLetter = "";

    private void GoToStep(int step)
    {
        if (completedSteps.Contains(step) || step == currentStep)
            currentStep = step;
    }

    private void OnPersonalNext(PersonalInfo info)
    {
        personalInfo = info;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void OnWorkNext(List<WorkEntry> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void OnWorkBack(List<WorkEntry> entries)
    {
        workEntries = entries;
        currentStep = 0;
    }

    private void OnReferencesNext(List<Reference> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void OnReferencesBack(List<Reference> refs)
    {
        references = refs;
        currentStep = 1;
    }

    private void OnCoverLetterNext(string text)
    {
        coverLetter = text;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private void OnCoverLetterBack(string text)
    {
        coverLetter = text;
        currentStep = 2;
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            personalInfo,
            new WorkHistory(workEntries),
            references,
            coverLetter);
        return await AppService.SubmitApplicationAsync(application);
    }
}

